  CREATE INDEX IX_NhatKyQuanTri_ThoiGian ON dbo.NhatKyQuanTri(ThoiGian DESC);
');
  EXEC sys.sp_executesql @stmt;

  SET @stmt = CONVERT(NVARCHAR(MAX),N'
PRINT N''Migration 10 hoan thanh: giu nguyen cac don cu khong co MaNguoiDung.'';
');
  EXEC sys.sp_executesql @stmt;

  IF EXISTS(SELECT 1 FROM dbo.SchemaMigrations WHERE Version=10)
   UPDATE dbo.SchemaMigrations SET FileName=N'010_ownership.sql',ChecksumSha256='8c9f0905d4fcf5ce88ade06f191345ca52c01385c48e5bf396a55afca8318829',AppliedBy=SUSER_SNAME() WHERE Version=10;
  ELSE INSERT dbo.SchemaMigrations(Version,FileName,ChecksumSha256,AppliedBy)
   VALUES(10,N'010_ownership.sql','8c9f0905d4fcf5ce88ade06f191345ca52c01385c48e5bf396a55afca8318829',SUSER_SNAME());
 END
 COMMIT;
 PRINT N'010_ownership.sql: OK';
END TRY
