    CONSTRAINT CK_QuyenLoiGoi_Translations CHECK(SoVideoDich>=0 AND DaDungVideoDich>=0 AND DaDungVideoDich<=SoVideoDich),
    CONSTRAINT CK_QuyenLoiGoi_Source CHECK(NguonXacNhan IN (''demo'',''payos''))
  );
