IF OBJECT_ID(''dbo.CongViecXuLy'',''U'') IS NULL
CREATE TABLE dbo.CongViecXuLy (
 MaCongViec BIGINT IDENTITY(1,1) NOT NULL CONSTRAINT PK_CongViecXuLy PRIMARY KEY,
 MaVideo INT NULL CONSTRAINT FK_CongViecXuLy_Video REFERENCES dbo.Video(MaVideo) ON DELETE SET NULL,
 MaNguoiDung INT NOT NULL CONSTRAINT FK_CongViecXuLy_NguoiDung REFERENCES dbo.NguoiDung(MaNguoiDung),
 Loai VARCHAR(20) NOT NULL CONSTRAINT CK_CongViecXuLy_Loai CHECK(Loai IN (''asr'',''translate'',''tts'',''export'')),
 TrangThai VARCHAR(20) NOT NULL CONSTRAINT DF_CongViecXuLy_TrangThai DEFAULT ''queued''
   CONSTRAINT CK_CongViecXuLy_TrangThai CHECK(TrangThai IN (''queued'',''running'',''completed'',''failed'',''cancelled'')),
 TienDo INT NOT NULL CONSTRAINT DF_CongViecXuLy_TienDo DEFAULT 0
   CONSTRAINT CK_CongViecXuLy_TienDo CHECK (TienDo BETWEEN 0 AND 100),
 Loi NVARCHAR(2000) NULL,
 SoLanThu INT NOT NULL CONSTRAINT DF_CongViecXuLy_SoLanThu DEFAU') +
    N'LT 0
   CONSTRAINT CK_CongViecXuLy_SoLanThu CHECK(SoLanThu BETWEEN 0 AND 100),
 NgayTao DATETIME2(0) NOT NULL CONSTRAINT DF_CongViecXuLy_NgayTao DEFAULT SYSUTCDATETIME(),
 NgayCapNhat DATETIME2(0) NOT NULL CONSTRAINT DF_CongViecXuLy_NgayCapNhat DEFAULT SYSUTCDATETIME()
);
';
  EXEC sys.sp_executesql @stmt;

  SET @stmt = CONVERT(NVARCHAR(MAX),N'
IF OBJECT_ID(''dbo.TepXuat'',''U'') IS NULL
CREATE TABLE dbo.TepXuat (
