 DuongDan NVARCHAR(500) NOT NULL,
 DungLuong BIGINT NOT NULL CONSTRAINT CK_TepXuat_DungLuong CHECK(DungLuong>=0),
 Sha256 CHAR(64) NOT NULL,
 NgayHetHan DATETIME2(0) NULL,
 NgayTao DATETIME2(0) NOT NULL CONSTRAINT DF_TepXuat_NgayTao DEFAULT SYSUTCDATETIME(),
 NgayCapNhat DATETIME2(0) NOT NULL CONSTRAINT DF_TepXuat_NgayCapNhat DEFAULT SYSUTCDATETIME()
);
');
