IF COL_LENGTH(''dbo.Video'',''ThoiLuong'') IS NULL ALTER TABLE dbo.Video ADD ThoiLuong DECIMAL(12,3) NULL;
IF COL_LENGTH(''dbo.Video'',''Sha256'') IS NULL ALTER TABLE dbo.Video ADD Sha256 CHAR(64) NULL;
IF COL_LENGTH(''dbo.Video'',''Nguon'') IS NULL ALTER TABLE dbo.Video ADD Nguon VARCHAR(20) NULL;
