-- 018_revenue_views.sql SHA256 19c167d09ad5260abe1105ee675e92d560ad460f093088ec9ac1102b60b6d673
BEGIN TRY
 BEGIN TRAN;
 DECLARE @gotLock INT,@apply BIT=1,@existing CHAR(64),@oldName NVARCHAR(100),@stmt NVARCHAR(MAX);
 EXEC @gotLock=sys.sp_getapplock @Resource=N'DubchefDB:SchemaMigrations',@LockMode=N'Exclusive',@LockOwner=N'Transaction',@LockTimeout=30000;
 IF @gotLock<0 THROW 51901,N'Failed to acquire schema migration lock',1;
 SELECT @existing=ChecksumSha256,@oldName=FileName FROM dbo.SchemaMigrations WITH(UPDLOCK,HOLDLOCK) WHERE Version=18;
 IF @existing IS NOT NULL BEGIN
  IF @existing<>'19c167d09ad5260abe1105ee675e92d560ad460f093088ec9ac1102b60b6d673' THROW 51902,N'Migration checksum mismatch',1;
  SET @apply=0;
 END
 ELSE IF @oldName IS NOT NULL AND NOT (18=14 AND @oldName=N'014_pricing.sql')
  THROW 51903,N'Unknown legacy migration entry; manual review required',1;
 IF @apply=1 BEGIN

  SET @stmt = CONVERT(NVARCHAR(MAX),N'/* Single source of daily revenue: Vietnamese calendar date, verified payOS only.
   Demo and unverified legacy amounts are separate; cross-currency totals forbidden. */
CREATE OR ALTER VIEW dbo.vw_DoanhThuNgay AS
SELECT CAST(DATEADD(HOUR,7,g.NgayThanhToan) AS DATE) AS Ngay,
 g.LoaiTien,
 COUNT_BIG(CASE WHEN g.NguonXacNhan=''payos'' THEN 1 END) AS SoGiaoDich,
 COALESCE(SUM(CASE WHEN g.NguonXacNhan=''payos'' THEN CONVERT(BIGINT,g.SoTien) ELSE 0 END),0) AS TongSoTien,
 COUNT_BIG(CASE WHEN g.NguonXacNhan=''demo'' THEN 1 END) AS SoGiaoDichMoPhong,
 COALESCE(SUM(CASE WHEN g.NguonXacNhan=''demo'' THEN CONVERT(BIGINT,g.SoTien) ELSE 0 END),0) AS TongTienMoPhong,
 COUNT_BIG(CASE WHEN g.NguonXacNhan=''legacy_unknown'' THEN 1 END) AS SoGiaoDichChuaXacMinh,
 COALESCE(SUM(CASE WHEN g.NguonXacNhan=''legacy_unknown'' THEN CONVERT(BIGINT,g.SoTien) ELSE 0 END),0) AS TongTienChuaXacMinh
FROM dbo.GiaoDich g WHERE g.Tr') +
    N'angThai=''success''
GROUP BY CAST(DATEADD(HOUR,7,g.NgayThanhToan) AS DATE),g.LoaiTien;
';
  EXEC sys.sp_executesql @stmt;

  SET @stmt = CONVERT(NVARCHAR(MAX),N'
CREATE OR ALTER VIEW dbo.vw_KiemTraDoanhThu AS
SELECT Ngay,LoaiTien,SoGiaoDich,TongSoTien,
 SoGiaoDichMoPhong,TongTienMoPhong,SoGiaoDichChuaXacMinh,TongTienChuaXacMinh
FROM dbo.vw_DoanhThuNgay;
');
  EXEC sys.sp_executesql @stmt;

  IF EXISTS(SELECT 1 FROM dbo.SchemaMigrations WHERE Version=18)
   UPDATE dbo.SchemaMigrations SET FileName=N'018_revenue_views.sql',ChecksumSha256='19c167d09ad5260abe1105ee675e92d560ad460f093088ec9ac1102b60b6d673',AppliedBy=SUSER_SNAME() WHERE Version=18;
  ELSE INSERT dbo.SchemaMigrations(Version,FileName,ChecksumSha256,AppliedBy)
   VALUES(18,N'018_revenue_views.sql','19c167d09ad5260abe1105ee675e92d560ad460f093088ec9ac1102b60b6d673',SUSER_SNAME());
 END
 COMMIT;
 PRINT N'018_revenue_views.sql: OK';
END TRY
BEGIN CATCH
 IF @@TRANCOUNT>0 ROLLBACK;
 THROW;
END CATCH;
GO

