 DECLARE @qualified2 NVARCHAR(300)=N''dbo.''+QUOTENAME(@oldPk2);
 EXEC sys.sp_rename @objname=@qualified2,@newname=N''PK_LichSuXuLyPhanHoi'',@objtype=N''OBJEC') +
    N'T'';
END;
';
  EXEC sys.sp_executesql @stmt;

  IF EXISTS(SELECT 1 FROM dbo.SchemaMigrations WHERE Version=19)
   UPDATE dbo.SchemaMigrations SET FileName=N'019_database_policies.sql',ChecksumSha256='2539a60dee06a872299212e5cca5121e3b36f5b635be7c112d8670f608d1595a',AppliedBy=SUSER_SNAME() WHERE Version=19;
  ELSE INSERT dbo.SchemaMigrations(Version,FileName,ChecksumSha256,AppliedBy)
   VALUES(19,N'019_database_policies.sql','2539a60dee06a872299212e5cca5121e3b36f5b635be7c112d8670f608d1595a',SUSER_SNAME());
